using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Greets a user by name")]
    public static string Greet([Description("The user's name")] string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";

    [McpServerTool, Description("Returns the current server time in UTC")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns application configuration data",
        MimeType = "application/json")]
    public static string GetAppSettings() =>
        """
        {
          "appName": "McpHttpServer",
          "version": "1.0.0",
          "features": {
            "logging": true,
            "caching": false,
            "maxConnections": 100
          },
          "environment": "development"
        }
        """;

    [McpServerResource(
        UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Lists available API endpoints",
        MimeType = "application/json")]
    public static string GetEndpoints() =>
        """
        {
          "endpoints": [
            { "path": "/mcp", "transport": "HTTP+SSE" },
            { "path": "/mcp", "transport": "Streamable HTTP" }
          ]
        }
        """;
}

